import {Image, Pressable, TextInput, View} from 'react-native';
import {ICheckList, ICheckListItem} from '../../../../helper';
import {CheckBox, Icon} from '@ui-kitten/components';
import {Dispatch, SetStateAction, useMemo, useRef, useState} from 'react';
import InputValueItem from './input-value-item';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import AssignCheckList from '../assign-checklist';
import {AssignTaskList} from '../../../task-detail-item/helper';
import DropdownCM from '../../../../../../components/DropDown';
import {ListDropdownCheckList} from './helper';
import {useTaskService} from '../../../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import {Color, Font, String} from '../../../../../../../constants';
import {useUserStore} from '../../../../../../../zutand/user-store';
import TextCM from '../../../../../../components/Text';
import useBoardStore from '../../../../../board/store';

type Props = {
  valueCheckList: ICheckListItem[];
  checkList: ICheckList;
  setCheckList: Dispatch<SetStateAction<ICheckList[]>>;
  listCheckList: ICheckList[];
  handleFocus: any;
  handleChangeValueName: (value: any, idCheckList?: string) => void;
  handleChangeValueCheckList: (
    value: any,
    idCheckList?: string,
    type?: string,
    index?: number,
  ) => void;
  handleUpdateCheckList: (name: string, checkListId?: string) => void;
  handleClearCheckListValue: (checkListId?: string, index?: number) => void;
  // assignTaskList?: AssignTaskList[];
};

const CheckListItem = ({
  checkList,
  handleFocus,
  handleChangeValueName,
  handleChangeValueCheckList,
  handleUpdateCheckList,
  handleClearCheckListValue,
  // assignTaskList,
  setCheckList,
  listCheckList,
  valueCheckList,
}: Props) => {
  const refInput = useRef<TextInput>(null);
  const refInputName = useRef<TextInput>(null);
  const [valueText, setValueText] = useState('');
  const [checkListName, setCheckListName] = useState(checkList?.name);
  const [modalAssign, setModalAssign] = useState(false);
  const [checkListSelect, setCheckListSelect] = useState<ICheckListItem>();
  const [typeSelectUser, setTypeSelectUser] = useState<'one' | 'all'>('one');

  const TaskService = useTaskService();
  const {listUser, listUserInTask} = useUserStore();

  const handleSubmit = (value: string, index: number) => {
    handleChangeValueCheckList(value, checkList.id, 'name', index);
  };

  const handleChangeSelect = (value: string) => {
    switch (value) {
      case 'delete':
        deleteCheckList();
        break;
      case 'unSelectAll':
        handleSelectOrUnSelectAll(false);
        break;
      case 'selectAll':
        handleSelectOrUnSelectAll(true);
        break;
      case 'unAssignAll':
        handleUnAssignAll();
        break;
      case 'assignAll':
        setTypeSelectUser('all');
        setModalAssign(true);
        break;
      default:
        break;
    }
  };

  const handleUnAssignAll = async () => {
    const prevCheckList = [...listCheckList];
    let checkIsCallApi: boolean[] = [];
    setCheckList(prev =>
      prev?.map(i => {
        const value = JSON.parse(i?.value || '[]');
        const newValue = value?.map((v: ICheckListItem) => {
          if (v.assign) {
            checkIsCallApi?.push(true);
          }
          return {
            ...v,
            assign: null,
          };
        });
        return {
          ...i,
          value: JSON.stringify(newValue),
        };
      }),
    );

    if (!checkIsCallApi?.length) {
      return;
    }

    const dataResp = await TaskService.updateCheckListTask({
      ...checkList,
      value: JSON.stringify(
        JSON.parse(checkList?.value || '[]')?.map((v: ICheckListItem) => ({
          ...v,
          assign: null,
        })),
      ),
    });
    if (!dataResp) {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Có lỗi xảy ra',
      });
      setCheckList(prevCheckList);
    }
  };

  const deleteCheckList = async () => {
    try {
      const dataResp = await TaskService.deleteCheckListById(
        checkList?.id as string,
      );
      if (dataResp) {
        setCheckList((prev: ICheckList[]) =>
          prev?.filter(i => i.id !== checkList?.id),
        );
      }
    } catch (error) {}
  };

  const handleSelectOrUnSelectAll = async (valueChange: boolean) => {
    try {
      const prevCheckList = [...listCheckList];
      let dataSelect;
      const newData = listCheckList?.map(checkListState => {
        if (checkListState?.id === checkList?.id) {
          const value = JSON.parse(checkListState?.value || '[]');
          if (value && value?.length) {
            const newValue = value?.map((v: any) => ({
              ...v,
              status: valueChange,
            }));
            dataSelect = {
              ...checkListState,
              value: JSON.stringify(newValue),
            };
            return {
              ...checkListState,
              value: JSON.stringify(newValue),
            };
          }
        } else {
          return checkListState;
        }
      }) as ICheckList[];
      setCheckList(newData);

      const dataResp = await TaskService.updateCheckListTask(dataSelect);
      if (!dataResp) {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
        setCheckList(prevCheckList);
      }
    } catch (error) {}
  };

  const handleSelectUserCheckList = async (value: any) => {
    const dataValue = JSON.parse(checkList?.value || '[]');
    const newDataValue = dataValue?.map((v: ICheckListItem) =>
      v.name === value?.name ? value : v,
    );
    const newCheckList = {
      ...checkList,
      value: JSON.stringify(newDataValue),
    };
    setCheckList(prev =>
      prev?.map(i => (i.id === newCheckList?.id ? newCheckList : i)),
    );

    const dataResp = await TaskService.updateCheckListTask(newCheckList);
    if (!dataResp) {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Có lỗi xảy ra',
      });
      setCheckList(prev =>
        prev?.map(i => (i.id === checkList?.id ? checkList : i)),
      );
    }
  };

  const handleAssignAll = async (valueData: any) => {
    const prevCheckList = [...listCheckList];
    setCheckList(prev =>
      prev?.map(i => {
        const value = JSON.parse(i?.value || '[]');
        const newValue = value?.map((v: ICheckListItem) => {
          return {
            ...v,
            ...valueData,
          };
        });
        return {
          ...i,
          value: JSON.stringify(newValue),
        };
      }),
    );
    const dataResp = await TaskService.updateCheckListTask({
      ...checkList,
      value: JSON.stringify(
        JSON.parse(checkList?.value || '[]')?.map((v: ICheckListItem) => ({
          ...v,
          ...valueData,
        })),
      ),
    });
    if (!dataResp) {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Có lỗi xảy ra',
      });
      setCheckList(prevCheckList);
    }
  };

  const handleSelect = (valueData: any) => {
    if (typeSelectUser === 'one') {
      handleSelectUserCheckList(valueData);
    } else if (typeSelectUser === 'all') {
      handleAssignAll(valueData);
    }
  };

  return (
    <View
      style={{
        paddingHorizontal: 10,
        marginBottom: 10,
      }}>
      <View
        style={{
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'space-between',
          columnGap: 8,
          marginBottom: 10,
        }}>
        <TextInput
          style={{
            paddingVertical: 6,
            flex: 1,
            color: Color.Text,
            fontFamily: Font.InterRegular400,
          }}
          onChangeText={setCheckListName}
          multiline
          ref={refInputName}
          onFocus={() => handleFocus(refInputName)}
          value={checkListName}
          onBlur={e => handleChangeValueName(e.nativeEvent.text, checkList?.id)}
        />
        <DropdownCM
          listDropdown={
            listUserInTask && listUserInTask?.length > 0
              ? ListDropdownCheckList
              : ListDropdownCheckList?.filter(t => t.id > 2)
          }
          onChangeItem={i => handleChangeSelect(i.value)}
        />
      </View>
      <View>
        {valueCheckList?.map((checkListValue, index) => (
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'space-between',
              rowGap: 10,
            }}
            key={index}>
            <View
              style={{
                flex: 1,
                flexDirection: 'row',
                alignItems: 'center',
                columnGap: 10,
              }}>
              <CheckBox
                checked={checkListValue?.status}
                onChange={nextChecked =>
                  handleChangeValueCheckList(
                    nextChecked,
                    checkList.id,
                    'status',
                    index,
                  )
                }
              />

              <InputValueItem
                handleFocus={handleFocus}
                checkListValueName={checkListValue?.name}
                handleChangeValueCheckList={handleSubmit}
                index={index}
              />
            </View>
            <View
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                columnGap: 8,
              }}>
              {listUserInTask && listUserInTask?.length > 0 && (
                <Pressable
                  onPress={() => {
                    setCheckListSelect(checkListValue);
                    setTypeSelectUser('one');
                    setModalAssign(true);
                  }}
                  style={{
                    width: 25,
                    height: 25,
                    borderRadius: 25 / 2,
                    borderWidth: !checkListValue?.assign ? 1 : 0,
                    borderStyle: 'dashed',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}>
                  {!checkListValue?.assign ? (
                    <Icon name="person-add" width={14} height={14} />
                  ) : (
                    <Image
                      style={{
                        width: 25,
                        height: 25,
                        borderRadius: 25 / 2,
                      }}
                      source={{
                        uri:
                          listUser?.find(
                            u =>
                              u.resourceId ===
                              checkListValue?.assign?.[0]?.userId,
                          )?.imageUrl || String.DEFAULT_IMAGE,
                      }}
                    />
                  )}
                </Pressable>
              )}
              <Pressable
                onPress={() => handleClearCheckListValue(checkList?.id, index)}>
                <Icon name="trash" fill={Color.Text} width={25} height={25} />
              </Pressable>
            </View>
          </View>
        ))}

        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            columnGap: 8,
            paddingVertical: 6,
          }}>
          <TextInput
            style={{
              paddingHorizontal: 10,
              paddingVertical: 12,
              flex: 1,
              fontFamily: Font.InterRegular400,
            }}
            ref={refInput}
            onFocus={() => handleFocus(refInput)}
            multiline={true}
            value={valueText}
            onChangeText={setValueText}
            allowFontScaling={false}
            placeholder="Add Item..."
            onSubmitEditing={e => {
              handleUpdateCheckList(e.nativeEvent.text, checkList?.id);
              setValueText('');
            }}
            onBlur={e => {
              handleUpdateCheckList(e.nativeEvent.text, checkList?.id);
              setValueText('');
            }}
          />
          {valueText && (
            <Pressable
              onPress={() => {
                handleUpdateCheckList(valueText, checkList?.id);
                setValueText('');
              }}
              style={{
                paddingHorizontal: 10,
                paddingVertical: 10,
                borderRadius: 8,
                backgroundColor: Color.BgPrimary,
              }}>
              <TextCM
                style={{
                  color: '#fff',
                }}>
                Thêm
              </TextCM>
            </Pressable>
          )}
        </View>
      </View>

      <ModalFullScreen
        isVisible={modalAssign}
        children={
          <AssignCheckList
            type="T"
            listUserInTask={listUserInTask}
            onClose={() => setModalAssign(false)}
            valueCheckList={checkListSelect}
            handleAssignCheckList={handleSelect}
          />
        }
      />
    </View>
  );
};

export default CheckListItem;
