import {View} from 'react-native';

import {styles} from './styles';
import {TaskGroup} from '../../../../model/interface/dashboard.interface';
import TableTaskCard from './TableTaskCard';

type Props = {
  listTask?: TaskGroup[];
  type?: string | null;
};
export default function DashboardTaskList({listTask, type}: Props) {
  return (
    <View style={styles.container}>
      {listTask?.map(item => {
        return <TableTaskCard item={item} key={item.listTaskId} type={type} />;
      })}
    </View>
  );
}
