import {
  Platform,
  Share,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import TextCM from '../../../../../../../../components/Text';
import {IAttractment} from '../../helper';
import {Color, NavigationName} from '../../../../../../../../../constants';
import {DateUtils} from '../../../../../../../../../utils';
import {useUtilsService} from '../../../../../../../../../hooks/apiHooks/useAPI';
import {useNavigation} from '@react-navigation/native';
import {Dispatch, SetStateAction, useMemo, useState} from 'react';
import BottomSheetCM from '../../../../../../../../components/BottomSheet';
import Action from '../modal-action';
import TextFieldCM from '../../../../../../../../components/TextField';
import ButtonCM from '../../../../../../../../components/Button';
import Clipboard from '@react-native-clipboard/clipboard';
import RNFS from 'react-native-fs';
import ReactNativeBlobUtil from 'react-native-blob-util';
import {getConfig} from '../../../../../../../../../services/httpClient';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {Divider, Icon} from '@ui-kitten/components';

type Props = {
  valueItem: IAttractment;
  setListAttractment: Dispatch<SetStateAction<IAttractment[]>>;
};

const AttractmentItem = ({valueItem, setListAttractment}: Props) => {
  const {t} = useTranslation();
  const {width} = useWindowDimensions();
  const [showBottomSheet, setShowBottomSheet] = useState('');
  const [nameFile, setNameFile] = useState(
    valueItem.filename
      ? valueItem?.filename?.split('.').slice(0, -1).join('.')
      : valueItem.url,
  );

  const typeFile = useMemo(
    () => valueItem?.filename?.split('.').slice(-1)[0],
    [valueItem?.filename],
  );

  const navigation = useNavigation<any>();
  const UtilsService = useUtilsService();

  const handleOpenFile = async (type: 'view' | 'copy') => {
    if (valueItem?.url) {
      if (type === 'copy') {
        Clipboard.setString(valueItem?.url);
      } else {
        navigation.navigate(NavigationName.WebviewScreen, {
          url: valueItem?.url,
        });
      }
      setShowBottomSheet('');
      return;
    }

    const formData = new FormData();
    formData.append('file', null);
    const params = {
      bucketName: valueItem?.bucketName,
      keyName: valueItem?.keyName,
      beanName: valueItem?.beanName,
    };
    const dataResp = await UtilsService.viewFile(formData, params);
    if (dataResp) {
      if (type === 'view') {
        navigation.navigate(NavigationName.WebviewScreen, {
          url: dataResp?.message,
        });
      } else {
        Clipboard.setString(dataResp?.message);
      }
      setShowBottomSheet('');
    }
  };

  const handleCloseBottomSheet = () => {
    setShowBottomSheet('');
    setNameFile(valueItem?.filename?.split('.').slice(0, -1).join('.'));
  };

  const handleChangeNameFile = async () => {
    try {
      if (!nameFile) {
        setShowBottomSheet('');
        setNameFile(valueItem?.filename?.split('.').slice(0, -1).join('.'));
        return;
      }
      const formData = new FormData();
      const dto = {
        ...valueItem,
        filename: valueItem?.filename ? `${nameFile}.${typeFile}` : nameFile,
      };
      formData.append('file', null);
      formData.append('dto', JSON.stringify(dto));
      const dataResp = await UtilsService.updateFile(formData, 'PUT');
      if (dataResp) {
        setShowBottomSheet('');
        setListAttractment(prev =>
          prev?.map(i => (i.id === valueItem?.id ? dataResp : i)),
        );
      }
    } catch (error) {}
  };

  const handleAction = (action: string) => {
    switch (action) {
      case 'rename':
        setShowBottomSheet('rename');
        break;
      case 'download':
        handleDownloadFile();
        break;
      case 'copy':
        handleOpenFile('copy');
        break;
      case 'delete':
        handleDelete();
        break;
      case 'view':
        handleOpenFile('view');
        break;
      default:
        break;
    }
  };

  const handleDelete = async () => {
    try {
      const dataResp = await UtilsService.deleteFile(valueItem?.id);
      if (dataResp) {
        setListAttractment(prev => prev?.filter(i => i.id !== valueItem?.id));
        setShowBottomSheet('');
      }
    } catch (error) {}
  };

  const handleDownloadFile = async () => {
    try {
      const toFile = `${
        Platform.OS === 'android'
          ? RNFS.DownloadDirectoryPath
          : RNFS.DocumentDirectoryPath
      }/${new Date().getTime()}_${valueItem?.filename}`;
      const dataBase64 = await ReactNativeBlobUtil.fetch(
        'GET',
        `${getConfig().BASE_URL}/services/etask/api/attachment/${
          valueItem?.id
        }`,
      )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.base64();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      if (dataBase64) {
        await RNFS.writeFile(toFile, dataBase64, 'base64');
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            await RNFS.unlink(toFile);
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      }
    } catch (error) {
    } finally {
      setShowBottomSheet('');
    }
  };

  const getIcon = () => {
    const attr = JSON.parse(valueItem?.attr || '{}');
    switch (attr?.type?.toLowerCase()) {
      case 'url':
        return (
          <Icon fill={'#366ae2'} name="link-2-outline" width={40} height={40} />
        );
      case 'png':
      case 'jpg':
      case 'ipeg':
        return (
          <Icon fill={'#366ae2'} name="image-outline" width={40} height={40} />
        );
      case 'file':
        return (
          <Icon fill={'#366ae2'} name="file-outline" width={40} height={40} />
        );
      default:
        return (
          <Icon fill={'#366ae2'} name="file-outline" width={40} height={40} />
        );
    }
  };

  return (
    <>
      <TouchableOpacity
        onPress={() => setShowBottomSheet('action')}
        style={{
          padding: 10,
          borderWidth: 1,
          borderColor: Color.borderColor,
          borderRadius: 8,
          rowGap: 10,
          width: (width - 40) / 2,
        }}>
        <View
          style={{
            alignItems: 'center',
            justifyContent: 'center',
          }}>
          {getIcon()}
        </View>
        <Divider />
        {<TextCM numberOfLines={1}>{nameFile}</TextCM>}
        <TextCM>
          {DateUtils.convertDateToDDMMYYYY_H_M(valueItem?.createdDate)}
        </TextCM>
        <TextCM numberOfLines={1}>
          {'Người tạo: ' + valueItem?.createdBy}
        </TextCM>
      </TouchableOpacity>

      <BottomSheetCM
        title="Thao tác"
        isVisible={showBottomSheet === 'action'}
        onClose={() => setShowBottomSheet('')}
        renderContent={
          <Action
            isDownload={valueItem?.filename ? true : false}
            setActionSelect={handleAction}
          />
        }
      />

      <BottomSheetCM
        title="Đổi tên"
        isVisible={showBottomSheet === 'rename'}
        onClose={handleCloseBottomSheet}
        withKeyboardAvoidingView={true}
        renderContent={
          <>
            <TextFieldCM
              multiline
              value={nameFile}
              onChangeText={setNameFile}
            />
            <ButtonCM
              disabled={!nameFile}
              label="Lưu"
              onPress={handleChangeNameFile}
            />
          </>
        }
      />
    </>
  );
};

export default AttractmentItem;
